(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[425],{6241:(e,t,i)=>{"use strict";i.r(t),i.d(t,{default:()=>o});var a=i(5155),n=i(8720);let r={eyebrow:"AI SEO",headline:"Rank in AI search engines,",headlineAccent:"not just Google.",subhead:"Google AI Overview, ChatGPT search, Perplexity, and Claude web search are already routing buying decisions. If your site isn't structured for LLMs to read and cite, you're invisible to the next generation of search. We fix that end-to-end.",outcomes:[{number:"3-5x",label:"citations in AI answers within 90 days"},{number:"8 weeks",label:"from audit to full AI-readiness"},{number:"100%",label:"white-hat, spec-compliant methods"},{number:"Every page",label:"structured for LLM ingestion"}],modulesEyebrow:"What we ship",modulesHeadline:"Five layers of AI-search optimisation.",modulesLead:"AI SEO is not a bolt-on. It's a systematic overhaul: technical foundation, content structure, machine-readable signals, monitoring, and iteration. We do all five so citations start showing up and keep showing up.",modules:[{number:"01",tag:"Foundation",title:"Technical AI-readiness audit",description:"Every AI crawler (GPTBot, ClaudeBot, PerplexityBot, Google-Extended, CCBot, and 15 more) has different requirements. We audit your robots.txt, llms.txt, sitemap, canonicals, structured data, and Markdown twins against every scanner spec in production today.",outputs:["AI-readiness scorecard (baseline + target)","llms.txt, robots.txt, sitemap.xml optimised for AI crawlers","Well-known endpoints (api-catalog, OAuth, signatures) where relevant"]},{number:"02",tag:"Structure",title:"Schema.org + JSON-LD everywhere",description:"Organization, WebSite, Article, FAQPage, HowTo, Product, Service, BreadcrumbList, Person. Every page gets the schema types that match its content, so Google's AI Overview and LLM search can pull structured answers directly.",outputs:["JSON-LD blocks on every route","Rich-result-eligible schema (Google Search Console validated)","Author + Organization graph for E-E-A-T signals"]},{number:"03",tag:"Content",title:"LLM-optimised content rewrites",description:"AI search rewards direct answers, specific numbers, cited claims, and tight semantic clustering. We rewrite your key pages so the answer to a query is in the first 200 words, backed by data your competitors don't cite.",outputs:["Answer-first paragraphs on every commercial page","Specific numbers + dates + named entities baked in","Markdown twin (/path/index.md) for every page"]},{number:"04",tag:"Distribution",title:"AI citation seeding",description:"LLM training data comes from specific sources: Common Crawl, Wikipedia, high-authority blogs, forums, GitHub, YouTube transcripts. We help you get named in those sources so future model rounds bake you in.",outputs:["High-authority guest posts and citations","Wikipedia + Wikidata presence where warranted","Structured PR and thought-leadership publishing plan"]},{number:"05",tag:"Reporting",title:"AI citation monitoring",description:"Weekly report on where your brand shows up in AI answers vs traditional search. Track queries where you appear in Google AI Overview, get cited in Perplexity, or come up in ChatGPT search. We rewrite whatever isn't converting.",outputs:["Weekly AI-citation dashboard","Query-level tracking across 4-5 AI engines","Bi-weekly optimisation call to steer next iteration"]}],processEyebrow:"Our process",processHeadline:"From audit to AI-native rankings,",processHeadlineAccent:"in 90 days.",processLead:"Traditional SEO takes 6-12 months to move. AI SEO moves faster because AI engines reindex constantly and reward structured signals immediately. We use both.",process:[{step:"Week 1",title:"AI-readiness audit",description:"We run every major AI-readiness scanner against your site and grade you on the same rubric AI crawlers use. Come out with a scorecard, a prioritised list of gaps, and a target lift number for month 3."},{step:"Weeks 2-3",title:"Technical foundation",description:"robots.txt, llms.txt, sitemap, canonicals, JSON-LD schemas, Markdown twins, content negotiation, well-known endpoints. Everything a modern AI crawler expects to find, published cleanly."},{step:"Weeks 4-6",title:"Content rewrites + signal-seeding",description:"Rewrite your top 10-20 commercial pages for answer-first structure. Seed authoritative citations across Wikipedia, high-authority blogs, and the sources AI models actually train on."},{step:"Week 7-8",title:"Monitoring live",description:"AI-citation dashboard live. Weekly report on which queries you're cited for, in which engines, at what position. First real AI-driven traffic starts landing."},{step:"Month 3+",title:"Optimisation cadence",description:"Bi-weekly review. New content commissioned for gaps, existing content rewritten for underperforming queries, structured data extended as AI search patterns evolve. Citations compound."}],guarantee:{headline:"Cited in Google AI Overview by month 3.",headlineAccent:"Or we work for free.",body:"We agree on a specific set of target queries before we start. If your site isn't cited in Google AI Overview or the equivalent for at least half of those queries by month 3, every hour of work after that is on us until it hits.",footnote:"Written into the contract. No small print, no clawback games."},faqs:[{question:"How is AI SEO different from traditional SEO?",answer:"Traditional SEO optimises for Google's blue links: keywords, backlinks, page speed. AI SEO optimises for machine consumption: structured data, direct-answer paragraphs, machine-readable content surfaces (Markdown twins, llms.txt), and getting cited by name in AI training data. We do both because AI engines still pull from the traditional index. But the tactics that move the needle are different."},{question:"Which AI search engines do you optimise for?",answer:"Google AI Overview (biggest volume), Perplexity, ChatGPT search, Claude web search, Gemini, DuckAssist, You.com, and Bing Copilot. Each has slightly different signals; we optimise for the underlying patterns rather than gaming any single engine."},{question:"Can you guarantee I'll rank in ChatGPT / Perplexity?",answer:"For Google AI Overview and Perplexity, yes — those are traceable and we back them with a work-for-free guarantee. For ChatGPT's default answers, no honest agency can guarantee that; the training cutoffs and grounding are opaque. What we can guarantee is that when ChatGPT search does browse your site, it will find well-structured, machine-readable content."},{question:"Isn't llms.txt just a fad?",answer:"Maybe. But so is every SEO signal until enough engines honor it. Right now llms.txt costs us nothing to ship, is honored by Perplexity and Anthropic's crawlers, and doesn't break anything. Same logic applies to Markdown twins, api-catalog, and the well-known endpoints. Cheap insurance against tomorrow's convention."},{question:"How is this different from just publishing more blog posts?",answer:"Content matters, but structure matters more for AI. A perfectly-written article without JSON-LD, canonicals, and machine-readable twins won't get cited by an AI agent. And a mediocre article with all the right signals often will. We fix the signal layer first, then the content layer."},{question:"What's the guarantee?",answer:"Cited in Google AI Overview (or the equivalent in your target engines) for at least half of the agreed target queries by month 3. Miss that, and every hour of work after is on us."}],faqEyebrow:"AI SEO",faqHeadingHighlight:"about AI SEO.",ctaHeadline:"Stop competing for blue links. Start owning AI answers.",ctaSubhead:"Book a free consultation. We'll run a live AI-readiness scan on the call and show you which queries your competitors already own — and how quickly we can flip them.",testimonials:[i(2903).r.tivan],relatedCaseStudies:["AI Revenue Operations \xb7 B2B SaaS Platform"]};function o(){return(0,a.jsx)(n.A,{content:r})}},8285:(e,t,i)=>{Promise.resolve().then(i.bind(i,6241))}},e=>{e.O(0,[836,861,939,968,441,255,358],()=>e(e.s=8285)),_N_E=e.O()}]);